# -*- coding: utf-8 -*-
import sys; sys.path.insert(0, "Tools/prd_ledger/86")
from _lib import c, table, save

c(1, "header lines 1-8; §2.1; §2.2 table (verbatim); §2.2", "positioning", "Today Habit tracker (App Store ID 1055295863, com.neybox.Today) by Neybox Digital Ltd. (also ships Pillow, the sleep app), released 2016-03-08, current 1.18 (2026-02-13), iOS 18 / watchOS 11, 11 localisations — one full-screen page per habit with a cover photo (stock or your own), swipe between habits; check-in by double-tap, 3D Touch, list swipe, widget, rich notification or Watch; 'cards' per habit (streak calendar, counter, custom chart, milestones, journal, photo gallery, Apple Health metrics, a stress/'limbic' card from ~Jul 2018); scheduling daily / weekdays / N per week (max 6) or month (max 25) / multiple check-ins a day; multiple reminders; badges; a profile with persistence statistics several found only by accident; iCloud Drive / Dropbox backup, no account, no server sync; passcode/Face ID lock; Watch app (~May 2017); Today widget (Oct 2016, removed Sep 2021, restored Nov 2021); dark mode (Oct 2021); URL scheme; no advertising ever; no social features. Reviewers say it is not a to-do list or workout tracker ('just a yes/no - did you hit the gym today?'). Listing (verbatim): " + table("## 2.2 What the store listing says", 0) + " — premium: photo covers, unlimited cards and habits, premium cards, backup, the lock.", "one-time $4.99 unlock (2016–~2021) → subscription + $299.99 lifetime", "mixed", "1,785 reviews, 70 storefronts, 18 languages, 2016-03-09 → 2026-07-13 (10.3 years), mean 3.97★; 166 hand codes; 636 checks", "none", "header", "app-specific", ["2337983734", "1720312452", "1359218702"], "", "ten-year corpus, front-loaded to 2016")

c(2, "How to read this; Ten warnings 2, 3, 4, 5, 7, 8, 10; §1.1 table (verbatim); §1.2 table (verbatim); §1.3 table (verbatim); §1.4; §1.5 table (verbatim); §1.6", "data-caveat", "Method and limits: every one of 1,785 reviews read in 18 batches in the original language (machine translation as a reading aid for zh/ja/ko/ru/tr/pl/bg, every quoted translation checked), hand codes with a quoted note per line, per-batch ID re-assertion caught three alignment drifts affecting 25 reviews; 166 codes, 25 unions, 636 checks, 8,300 computed facts, no number typed by hand; no duplicates, zero repeat authors, 60 edited, 254 with votes (max 82); the corpus is front-loaded — 645 reviews from 2016, 45.32% in E1 — so any global percentage is mostly a statement about 2016–17 ('Part 7 is not optional reading'); reviews decayed 59.1/month in E1 → 1.7/month in E5 (E5 59, E6 13 — directional only); no version field (Apple's history back to Mar 2020 only); 22 China-storefront reviews in English; six of 70 storefronts ≥50. Bands (verbatim): " + table("## 1.5 Signal thresholds", 0) + " — 0.1% ≈ 2, 5% ≈ 89.", "n/a", "mixed", "1,785/1,785 read; 166 codes; 636 checks; E1 45.32%; E5 59; E6 13", "none", "method", "generalisable", ["1345853521"], "", "")

c(3, "Warning 1, 6, 9; §1.6 #1", "data-caveat", "This corpus is not the app's rating: corpus 3.97★ vs every public storefront mean 4.5–4.8★ — 'written reviews here skew far more negative than silent star taps'; selection runs both ways (the 2016 launch wave and the 2022 black-screen wave are both bursts of motivated writers); 188 reviewers state they paid — a self-selected 10.53%, not a conversion rate.", "n/a", "mixed", "3.97★ vs public 4.5–4.8★; paid 188 / 10.53%", "none", "High-priority", "generalisable", ["1345853521"], "", "")

c(4, "§0.1; §3.2 (design)", "insight", "The product's differentiator is visual and it worked for ten years: PR_DESIGN 460 (25.77%, 4.33★, 2016 → 2026), the single largest theme; with the per-habit cover photo (PR_PHOTOS 97, 5.43%) the visual union is 523 (29.30%, 4.36★); reviewers treat it as the mechanism, not decoration — 'I'm a very visual person, so the combination of large pictures and colourful calendars/graphs is great. I really feel motivated to tick things off, more than any other habit app' (4★); custom backgrounds named as the one reason productivity improved most across 15 trackers in three years; 'It sets a craving, when I see the image, I want to accomplish the goal'; paired with simplicity (PR_SIMPLE 361, 20.22%, 4.68★) this is what 'best in category' rests on — PR_BEST 204 (11.43%), 4.78★, the highest mean of any large theme.", "full-screen photo per habit; free stock covers, paid custom", "praise", "PR_DESIGN 460 / 25.77% / 4.33★; visual union 523 / 29.30%; PR_PHOTOS 97; PR_SIMPLE 361 / 4.68★; PR_BEST 204 / 4.78★", "build-free", "High-priority", "generalisable", ["2337983734", "1478570559", "2636687666", "3581019264", "3610997192"], "", "a photo per habit is a craving mechanism, not decoration")

c(5, "§0.2; §3.2 (cards)", "contradiction", "The second differentiator — 'cards' — is loved by a minority and ignored by most: PR_CARDS 70 (3.92%, 4.69★), the depth union 192 (10.76%, 4.72★) — what power users name when explaining why they chose Today over a prettier-but-thinner rival ('the deciding factor was the extensibility of supplementary information via cards', jp 5★, running it alongside Momentum and Habity); but the corpus's most specific negative is NEG_FEATURE_UNUSED 15 (0.84%, 2.80★) — 'cards that are unusable in 95% cases'; 'those cards aren't really needed'; 'photos per habit are more of a gimmick at first' — and UX_CONFUSE 74 (4.15%) cannot work out the custom chart, counter or milestone card; 'the cards are simultaneously the reason power users pay and a source of confusion for everyone else'.", "per-habit data cards (counters, charts, Health, journal)", "mixed", "PR_CARDS 70 / 4.69★; depth union 192 / 10.76% / 4.72★; NEG_FEATURE_UNUSED 15 / 2.80★; UX_CONFUSE 74 / 4.15%", "undecided", "Very strong", "generalisable", ["1524523819", "3644769024", "1478423070", "1520730080", "1700023106", "2053507045"], "", "depth features convert the few and confuse the many")

c(6, "§0.3; §0.3 table (verbatim); §3.3", "must-never-break", "Reliability, not features, destroyed this product: U:bug_any 469 (26.27%, 2.89★); U:reliability (crash, won't launch, lag, glitch, broken by update) 234 (13.11%, 2.71★); bug mentions rise 12.36% → 50.85% of reviews from E1 to E5 while praise falls 77.87% → 33.9%; the corpus mean falls monotonically across five eras 4.16 → 4.14 → 3.59 → 3.51 → 3.07. Largest defect families (verbatim): " + table("## 0.3 Reliability", 0), "n/a", "1★-burst", "bug_any 469 / 26.27%; reliability 234 / 2.71★; mean 4.16 → 3.07; CRASH 126; WATCH 88; PERF 70; NOTIF 63; LAUNCH 58 / 2.26★; SWIPE 39; WIDGET 35; SYNC 32", "must-never-break", "High-priority", "generalisable", ["5541959561", "5953889344", "4921815578", "1611850727", "2433135123"], "", "")

c(7, "§0.4; §3.3 (perf); §8.1", "must-never-break", "A performance bug that scales with success: the app slows in proportion to accumulated check-ins — BUG_PERF 70 (3.92%), 0.74% of E1 → 16.95% of E5; 'it takes about 5 seconds to register, if I'm registering a long streak of 50 day's or so, which is how I've been using it for 3 years, it takes so long I've stopped bothering' (gb 1★); 'past 1,000 days a single tap means a mysterious freeze then a crash' (jp 1★); '200 check-ins is not really a large amount of data; the storage must be inefficiently programmed' (de 3★); 'It can take over a minute from when you mark something as done… I've contacted support multiple times over the past 6 months' (1★); 'a habit tracker that punishes long streaks with latency drives away exactly the users who proved the product works' — 17 of the 70 also record leaving, being blocked or threatening to leave.", "check-in latency grows with history size", "churn", "BUG_PERF 70 / 3.92%, 0.74% → 16.95%; 17 of 70 churn signals", "must-never-break", "Very strong", "generalisable", ["3827656315", "9295872427", "11596711598", "8580429365", "1527351492"], "", "")

c(8, "§0.5; §3.3 (watch); §8.5 reference", "timeline", "The Apple Watch app was requested for 14 months, shipped and never worked properly: REQ_WATCH 34 (1.90%) from 2016-03-11; shipped ~May 2017; from then BUG_WATCH 88 (4.93%, 2.98★) vs 21 praising it — check-ins revert ('several check ins I did earlier had reverted to not done'; 'I tap an icon to say I've done it, then 20 minutes late it's unchecked again!!'), phone and watch disagree, the complication is unavailable on most watch faces ('there is only one watch face that'll work with this app'); requests for Infograph complications (2018) recur for seven years, never answered.", "Watch app shipped 2017, sync unreliable, complication limited", "complaint", "REQ_WATCH 34; BUG_WATCH 88 / 4.93% / 2.98★; PR_WATCH 21; Infograph requests 10 over 7 years", "must-never-break", "Very strong", "generalisable", ["1620769515", "1920258131", "7720157586", "5953889344", "2056463243"], "", "a shipped-but-unreliable companion app is a larger negative than its absence")

c(9, "§0.6; §0.6 table (verbatim); §8.9", "timeline", "The free tier went 1 → 3 → 5 habits, then back to 1 — and the complaint came back with it (verbatim): " + table("## 0.6 The free tier went", 0) + " — at launch one habit: 71 complaints in 2016 alone, the dominant theme of the first fortnight; on ~22 March 2016 the developer raised it to three and reviewers noticed within a day ('because they actually listened to there customers I just paid full price for it!', 5★); then between January 2017 and December 2020 not one review complains the free tier allows only one habit; the complaint returns in 2022 ('you can only track ONE habit with the free version and can't add any cards… If they had just advertised this as a paid app, it would have been fair', 2★; 'I understood the free version allowed up to 3', 1★); the 5-habit stage rests on a single review; one-habit complaints average 1.97★ (78) — the lowest of any monetisation code — vs 3.60★ for three-habit complaints (67): 'the same grievance, attached to a tier three times wider, arrives with a rating 1.63 stars higher' (two groups six years apart, direction corroborated by the four-year silence and by reviewers narrating the change).", "free cap 1 → 3 (Mar 2016) → 5 (2017, n=1) → 1 (~2022)", "1★-burst", "MON_FREE1 78 / 1.97★; MON_FREE3 67 / 3.60★; 0 cap complaints 2017–2020", "product-rule", "High-priority", "generalisable", ["1351843491", "8311997753", "8362191635", "1918053513", "1346837988", "9591308969"], "", "a natural experiment: widening the cap silenced the complaint for four years; narrowing it re-imported it verbatim")

c(10, "§0.7; §0.7 table (verbatim); §2.3 pricing history table (verbatim); §8.10", "timeline", "Pricing: a one-time $4.99 unlock was an asset; it is now a $299.99 tier — PR_ONETIME 23 (1.29%, 4.61★), U:pro_pricing 124 (6.95%, 4.75★): 'Paying once (4.99) for all these features is the prime reason I use this app as a Habit Tracker compared to others'; 'some apps out there have a yearly subscription circa £30… this one is a steal at £5'; as of 2026-09-13 the one-time unlock no longer exists (verbatim): " + table("## 0.7 Pricing", 0) + " — reviewers found this first: 'why is Today Premium $10 per year, but ALL Premium Features are $300 ❓'; 'premium used to be $4.99 and now… $299.99' (gt 2★); 'I paid for this app and reviewed it years ago (when it was under a different pricing model)… for the $300 you're asking for now'; MON_SUBSCRIPTION 8, all from 2022-07-21, 2.62★ — no review welcomes the subscription. Pricing history (verbatim): " + table("## 2.3 Free / paid / trial", 1), "one-time ~$4.99 → $3.99/mo, $9.99/yr, $299.99 lifetime", "churn", "PR_ONETIME 23 / 4.61★; pro_pricing 124 / 4.75★; MON_SUBSCRIPTION 8 / 2.62★; lifetime $299.99 vs annual $9.99", "product-rule", "Meaningful", "generalisable", ["1626756462", "1708111245", "8946229677", "8448197948", "13865667618"], "", "a lifetime price 30× the annual reads as a price designed not to be paid")

c(11, "§0.8; §8.11 reference", "timeline", "The app stopped shipping for 1,030 days — starting with a build that would not launch: Apple's history shows 1,030 days between 1.9.63 (2022-11-09) and 1.10 (2025-09-04), zero releases in 2023 or 2024; the first black-screen review is dated 2022-11-09 ('after the 2022.11.09 version update the app won't open', cn 3★) and eleven more follow within six weeks — then nothing was shipped to fix it for two years and ten months; DEV_STALE 67 (3.75%, 3.01★) and 20.34% of E5 reviews; users audited the developer themselves ('no update in 2 years… email bounces because the embedded address is toda@neybox.com… Odd because sister app Pillow is working well'; 'is the team shifting focus to Pillow?'); 11 releases Sep 2025 → Feb 2026 but E6 has only 13 reviews.", "abandoned 2022–2025 with a launch-breaking last build", "1★-burst", "1,030 days no release; black-screen 12 in 6 weeks; DEV_STALE 67 / 20.34% of E5", "must-never-break", "Very strong", "generalisable", ["9271340335", "12543093674", "5060119494"], "", "the last build before a hiatus is the one users live with for years")

c(12, "§2.3 table (verbatim); §2.3", "monetization", "Free / paid classification (verbatim): " + table("## 2.3 Free / paid / trial", 0) + " — habit tracking free but capped at 1 habit today; custom photo covers moved behind payment after being free, taking existing covers with it; cards beyond a small number, premium cards, backup/restore and the Face ID lock are paid (one objects on principle to paying for a lock); reminders, widget, Watch and Health free; no advertising ever; no trial — the free tier is the trial, and a real trial was the most-requested monetisation change in 2016 (MON_TRIAL_REQ 33, 1.85%); the one-time → subscription transition is bounded between Aug 2021 and Jul 2022.", "free: 1 habit, reminders, widget, Watch, Health; paid: habits, covers, cards, backup, lock; no trial", "mixed", "MON_TRIAL_REQ 33 / 1.85%; 112 reviews name a price", "undecided", "table", "app-specific", ["8311997753", "1918053513"], "", "")

c(13, "§2.4; §2.5", "must-never-break", "Data and privacy: the label declares no tracking; PR_PRIVACY 4, PR_NOADS 7, PR_SECURITY 3 vs PRIV_CONCERN 4 — three independent reports across three languages and three years that the paid privacy lock leaks the habit list: 'What is the point of protecting your goals with password / touchid / faceid if 3D Touch widget reveals all my habits even if I force-close the app?' (ua 4★); 'If the app keep opening on the background, no password is required to launch the app' (3★); 'can you briefly see the configured habits just before the fingerprint screen?' (jp 5★). Not establishable: any download/revenue figure, exact dates of the 3→5 and 5→1 cap changes, the date the one-time unlock was withdrawn, whether App Store replies were posted (replies by email and Twitter reported both ways: PR_DEV 39, SUP_NORESP 25).", "paid privacy lock leaks via widget / 3D Touch / background", "complaint", "PRIV_CONCERN 4 (lock leak 3); PR_PRIVACY 4; PR_NOADS 7", "must-never-break", "Weak", "generalisable", ["5116388115", "2004605175", "1449566698"], "", "a paid privacy feature that leaks is worse than none")

save("w")
